package com.apiautomation.tests;
import com.apiautomation.base.*;import com.apiautomation.utils.TestDataFactory;import org.testng.annotations.Test;import static org.hamcrest.Matchers.*;
public class UserApiTests extends BaseTest {@Test public void ownProfileAndUpdateWorkAndUnauthorizedCasesFail()throws Exception{String e=TestDataFactory.email(),p=TestDataFactory.password();try{var created=auth.register("Profile User",e,p).then().statusCode(201).extract().response();long id=Long.parseLong(created.path("id").toString());String token=auth.login(e,p).then().statusCode(200).extract().path("accessToken");var noToken=users.getUser(id,null);noToken.then().statusCode(401);var bad=users.getUser(id,"not-a-jwt");bad.then().statusCode(401);var get=users.getUser(id,token);get.then().statusCode(200).body("password",nullValue()).body("id",equalTo((int)id));assertTime(get,TestConfig.apiThreshold());users.updateUser(id,java.util.Map.of("name","Updated","email",e),token).then().statusCode(200).body("name",equalTo("Updated"));org.testng.Assert.assertEquals(db.find(e).name(),"Updated");}finally{db.cleanup(e);}}
 @Test public void deletingAsCustomerForbiddenAndUnknownUserNotFound()throws Exception{String e=TestDataFactory.email();try{long id=Long.parseLong(auth.register("No Delete",e,TestDataFactory.password()).then().statusCode(201).extract().path("id").toString());String token=auth.login(e,TestDataFactory.password()).then().extract().path("accessToken");users.deleteUser(id,token).then().statusCode(403);users.deleteUser(id,null).then().statusCode(401);users.getUser(999999999,null).then().statusCode(401);}finally{db.cleanup(e);}}
}
